from collections import deque

def maxWidth(root):
    if not root:
        return 0
    queue = deque([(root, 0)])
    max_w = 0
    while queue:
        lvl_size = len(queue)
        _, left_pos = queue[0]
        for _ in range(lvl_size):
            node, pos = queue.popleft()
            if node.left:
                queue.append((node.left, 2*pos+1))
            if node.right:
                queue.append((node.right, 2*pos+2))
        max_w = max(max_w, pos - left_pos + 1)
    return max_w
